_relu_ext = load_inline(
    name="relu_fp16_ext",
    cpp_sources=_cpp_source,
    cuda_sources=_cuda_source,
    functions=["forward"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model using a custom CUDA fp16 ReLU kernel.
    """
    def __init__(self):
